method.description:
Starts sampling the availability of every backend on a background thread. [signal backend_availability_changed] is emitted when a backend becomes available or unavailable.
[param poll_interval_ms] is the base interval between samples in milliseconds; [code]0[/code] selects 1000. [param debounce_samples] is the number of consecutive samples that must agree before a change is reported; [code]0[/code] selects 2, and [code]1[/code] reports changes immediately. [param backoff_max_ms] is the longest interval, to which the interval doubles while nothing changes; [code]0[/code], or a value not greater than [param poll_interval_ms], keeps the interval constant. If [param auto_power_manage] is [code]true[/code], sampling stops while the system is suspended, where [method is_auto_power_management_supported] returns [code]true[/code].
The first sample of each backend sets a baseline and is not reported. [signal availability_baseline_established] is emitted once the baseline is set.
Returns [constant GodotPrismBackend.PRISM_OK] on success, [constant GodotPrismBackend.PRISM_ERROR_RANGE_OUT_OF_BOUNDS] if an integer argument is negative or greater than [code]4294967295[/code], [constant GodotPrismBackend.PRISM_ERROR_INVALID_OPERATION] if monitoring is already active, and [constant GodotPrismBackend.PRISM_ERROR_INTERNAL] if monitoring cannot be started.
[codeblock]
func _ready() -> void:
    Prism.backend_availability_changed.connect(_on_availability_changed)
    var err := Prism.start_availability_monitoring()
    if err != GodotPrismBackend.PRISM_OK:
        push_error("Monitoring failed: %s" % Prism.get_error_string(err))

func _on_availability_changed(id: int, backend_name: String, available: bool) -> void:
    print("%s: %s" % [backend_name, available])
[/codeblock]
